mapper.select:
SELECT task.id, pro.id 'project.id', pro.`name`'project.name', pro.short_name 'project.shortName', pro.serial_number 'project.serialNumber', ord.order_number, ord.id 'orderId', fac.id 'factory.id', fac.`name` 'factory.name', shop.id 'workshop.id', shop.`name` 'workshop.name', line.id 'productionLine.id', line.`name` 'productionLine.name', line.type 'line.type', team.id, plan.id 'plan.id', plan.`name` 'plan.name', plan.date 'plan.date', plan.quantity_work 'plan.quantityWork', enc.id 'productId', enc.`name` 'name', enc.length, cess.id 'process.id', cess.name 'process.name', task.task_quantity 'taskQuantity', task.complete_quantity 'completeQuantity', task.ask_complete_time 'askCompleteTime', enc.serial_number 'serialNumber', enc.category 'category', enc.plate, enc.color, enc.material, enc.thickness, enc.coating, enc.plating FROM mes_enclosure_task_order ord LEFT JOIN mes_enclosure_task task ON ord.id = task.task_order_id LEFT JOIN tech_enclosure enc ON task.product_id = enc.id LEFT JOIN enclosure_plan plan ON enc.enclosure_plan_id = plan.id LEFT JOIN contract_project pro ON enc.project_id = pro.id LEFT JOIN mes_building_factory fac ON task.factory_id = fac.id LEFT JOIN mes_building_workshop shop ON task.workshop_id = shop.id LEFT JOIN mes_enclosure_production_line line ON task.production_line_id = line.id LEFT JOIN mes_enclosure_team team ON task.team_id = team.id LEFT JOIN mes_enclosure_process cess ON task.process_id=cess.id WHERE task.bool_delete_enum = 0
AND enc.serial_numberLIKE CONCAT('%', #{serialNumber},'%')
AND enc.area_id =#{areaId}
AND enc.project_id =#{projectId}
AND enc.project_id IN
#{projectId}
AND task.team_id IN
#{teamId}
AND ord.id = #{taskOrderId}
and task.bool_complete_enum=0

SELECT task.id, pro.id 'project.id', pro.`name`'project.name', pro.short_name 'project.shortName', pro.serial_number 'project.serialNumber', ord.order_number, ord.id 'orderId', fac.id 'factory.id', fac.`name` 'factory.name', shop.id 'workshop.id', shop.`name` 'workshop.name', line.id 'productionLine.id', line.`name` 'productionLine.name', line.type 'line.type', team.id, pm.id 'monomer.id', pm.name 'monomer.name', area.id 'area.id', area.`name` 'area.name', enc.id 'productId', enc.`name` 'name', enc.length, cess.id 'process.id', cess.name 'process.name', task.task_quantity 'taskQuantity', task.complete_quantity 'completeQuantity', task.ask_complete_time 'askCompleteTime', enc.serial_number 'serialNumber', enc.category 'category', enc.plate, enc.color, enc.material, enc.thickness, enc.coating, enc.plating FROM mes_enclosure_task_order ord LEFT JOIN mes_enclosure_task task ON ord.id = task.task_order_id LEFT JOIN tech_enclosure enc ON task.product_id = enc.id and enc.bool_delete_enum = 0 LEFT JOIN plan_monomer pm ON enc.monomer_id = pm.id and pm.bool_delete_enum = 0 LEFT JOIN plan_area area ON enc.area_id = area.id and area.bool_delete_enum = 0 LEFT JOIN contract_project pro ON enc.project_id = pro.id and area.bool_delete_enum = 0 LEFT JOIN mes_building_factory fac ON task.factory_id = fac.id and area.bool_delete_enum = 0 LEFT JOIN mes_building_workshop shop ON task.workshop_id = shop.id and area.bool_delete_enum = 0 LEFT JOIN mes_enclosure_production_line line ON task.production_line_id = line.id and area.bool_delete_enum = 0 LEFT JOIN mes_enclosure_team team ON task.team_id = team.id and area.bool_delete_enum = 0 LEFT JOIN mes_enclosure_process cess ON task.process_id=cess.id and area.bool_delete_enum = 0 WHERE task.bool_delete_enum = 0
AND enc.serial_number LIKE CONCAT('%', #{serialNumber},'%')
AND enc.area_id =#{areaId}
AND enc.project_id =#{projectId}
AND enc.project_id IN
#{projectId}
AND task.team_id IN
#{teamId}
AND ord.id = #{taskOrderId}
and task.bool_complete_enum=0

SELECT enc.*, pro.id 'project.id', pro.`name` 'project.name', pro.short_name 'project.shortName', pro.serial_number 'project.serialNumber', com.quantity 'producedQuantity', IFNULL(com.quantity*enc.length ,0) 'totalLength', com.create_time 'completeTime', com.user_id 'completeUserId', us.name 'completeUserName' FROM mes_building_complete com INNER JOIN tech_enclosure enc ON com.product_id = enc.id LEFT JOIN contract_project pro ON pro.id = enc.project_id LEFT JOIN sys_user us ON com.user_id = us.id where com.bool_delete_enum=0 and com.task_type_enum=4
AND com.project_id = #{projectId}
AND enc.category = #{category}
AND date(com.create_time) >= date(#{startTime})
AND date(com.create_time) <= date(#{endTime})

SELECT enc.*, pro.id 'project.id', pro.`name` 'project.name', pro.short_name 'project.shortName', pro.serial_number 'project.serialNumber', com.quantity 'producedQuantity', IFNULL(com.quantity*enc.length ,0) 'totalLength', com.create_time 'completeTime', com.user_id 'completeUserId', us.name 'completeUserName' FROM mes_building_complete com INNER JOIN tech_enclosure enc ON com.product_id = enc.id LEFT JOIN contract_project pro ON pro.id = enc.project_id LEFT JOIN sys_user us ON com.user_id = us.id where com.bool_delete_enum=0 and com.task_type_enum=4
AND com.project_id = #{projectId}
AND enc.dictionary_id = #{dictionaryId}
AND date(com.create_time) >= date(#{startTime})
AND date(com.create_time) <= date(#{endTime})

SELECT IFNULL(SUM(a.quantity*a.length ) ,0)/1000 FROM ( SELECT com.quantity, enc.length FROM mes_building_complete com LEFT JOIN tech_enclosure enc ON com.product_id = enc.id WHERE com.bool_delete_enum = 0 and com.task_type_enum=4
AND enc.category = #{category}
AND date_format ( com.create_time, '%Y' ) = date_format( #{time}, '%Y')
) a

SELECT IFNULL(SUM(a.quantity*a.length ) ,0)/1000 FROM ( SELECT com.quantity, enc.length FROM mes_building_complete com LEFT JOIN tech_enclosure enc ON com.product_id = enc.id WHERE com.bool_delete_enum = 0 and com.task_type_enum=4
AND enc.dictionary_id = #{dictionaryId}
AND date_format ( com.create_time, '%Y' ) = date_format( #{time}, '%Y')
) a

SELECT pro.id 'project.id', pro.name 'project.name', pro.short_name 'project.shortName', pro.serial_number 'project.serialNumber', shop.id 'workshop.id', shop.name 'workshop.name', rep.production_line_id 'line.id', line.name 'line.name', rep.team_id, rep.price, SUM( rep.quantity * enc.length ) 'totalLength' FROM mes_enclosure_produce_team_report rep LEFT JOIN tech_enclosure enc ON rep.product_id = enc.id LEFT JOIN contract_project pro ON enc.project_id = pro.id LEFT JOIN mes_enclosure_production_line line ON rep.production_line_id=line.id LEFT JOIN mes_building_workshop shop ON rep.workshop_id=shop.id WHERE rep.bool_delete_enum=0
AND pro.id =#{projectId}
AND pro.id in
#{productId}
AND enc.category =#{category}
AND date(rep.create_time) >= date(#{startTime})
AND date(rep.create_time) <= date(#{endTime})
GROUP BY pro.id, rep.workshop_id, rep.production_line_id, rep.team_id, rep.price ORDER BY rep.workshop_id ASC, rep.production_line_id ASC, rep.team_id asc, pro.id DESC, rep.price ASC

SELECT enc.id productId, enc.id id, task.id task_id, task.factory_id, task.workshop_id, task.production_line_id, enc.*, task.task_quantity, task.complete_quantity AS warehouse_quantity, task.factory_id , task.ask_complete_time, pro.id 'project.id', pro.NAME 'project.name', pro.short_name 'project.short_name', pro.serial_number 'project.serial_number', plan.`id` 'plan.id', plan.`name` 'plan.name', task.bool_printed 'boolPrinted' FROM mes_enclosure_task task LEFT JOIN tech_enclosure enc ON task.product_id = enc.id AND enc.bool_delete_enum = 0 LEFT JOIN contract_project pro ON pro.id = enc.project_id AND pro.bool_delete_enum = 0 LEFT JOIN enclosure_plan plan ON plan.id = enc.enclosure_plan_id AND plan.bool_delete_enum = 0 WHERE task.bool_delete_enum =0
AND task.project_id = #{projectId}
AND task.plan_id = #{planId}
AND task.category = #{category}
AND task.production_line_id = #{lineId}
AND enc.name LIKE CONCAT('%',#{name},'%')
AND enc.serial_number LIKE CONCAT('%',#{serialNumber},'%')
AND enc.specification LIKE CONCAT('%',#{specification},'%')
AND enc.material LIKE CONCAT('%',#{material},'%')
AND task.complete_quantity = 0
AND (task.complete_quantity > 0 and task.complete_quantity < task.task_quantity)
AND task.complete_quantity = task.task_quantity

SELECT enc.*, task.task_quantity - task.complete_quantity as actualQuantity, cp.id 'project.id', cp.name 'project.name', cp.short_name 'project.short_name', cp.serial_number 'project.serial_number', m.id 'monomer.id', m.name 'monomer.name', ar.id 'area.id', ar.name 'area.name', process.id as 'process.id', process.name as 'process.name' FROM mes_enclosure_task task INNER JOIN tech_enclosure enc ON task.product_id = enc.id LEFT JOIN contract_project cp ON cp.id = enc.project_id left join plan_monomer m on enc.monomer_id = m.id and m.bool_delete_enum = 0 left join plan_area ar on enc.area_id = ar.id and ar.bool_delete_enum = 0 LEFT JOIN mes_enclosure_process process ON task.process_id = process.id where task.bool_delete_enum=0 AND task.task_quantity - task.complete_quantity > 0
AND task.area_id = #{areaId}
AND task.process_id = #{processId}
